using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Threading.Tasks;

namespace LiveScore.PushEventListener.Demo
{
    class Program
    {
        private const int MaxAttempts = 10;
        private const int MillisecondsTimeout = 30 * 1000;
        private static Dictionary<string, StreamReader> readers;
        private static int attempts;

        static void Main(string[] args)
        {
            Console.WriteLine("Hello World!");
            readers = new Dictionary<string, StreamReader>();

            Task.Run(async () => { await Start(1); });

            Console.ReadLine();
        }

        public static async Task Start(byte sportId)
        {
            var regions = new Dictionary<string, string> {
                {"am", "f5zwq9btg3wwg66upm84ntua" },
                {"intl", "5zn9j3p4qd3wzrujvfx7mngn" },
                {"other", "npc9md73nrwhykuepets3nqf" }
            };


            while (attempts < MaxAttempts)
            {
                attempts += 1;

                Console.WriteLine($"Start Listening Attempts: {attempts} at {DateTime.Now}");

                await StartListening(sportId, regions);

                readers = new Dictionary<string, StreamReader>();

                await Task.Delay(MillisecondsTimeout);
            }

        }

        private static async Task<bool> StartListening(byte sportId, Dictionary<string, string> regions)
        {
            foreach (var regionSetting in regions)
            {
                if (!readers.ContainsKey(regionSetting.Key))
                {
                    var req = CreateSubscribeRequest(regionSetting.Key, regionSetting.Value);

                    StreamReader reader = CreateStreamReader(req);

                    readers.Add(regionSetting.Key, reader);
                }
            }

            var isFailed = false;

            while (!isFailed)
            {
                Console.WriteLine($"Created {readers.Count} readers");

                var tasks = readers.Select(x => Task.Factory.StartNew(() => { ProcessPayloads(x.Value, x.Key); }));
                
                try
                {
                    await Task.WhenAll(tasks);
                }
                catch (AggregateException ae)
                {
                    foreach (var e in ae.InnerExceptions)
                    {
                        Console.WriteLine($"{ DateTime.Now } Error while listening feed for sportId {sportId}", ae);
                    }
                    
                    isFailed = true;
                }                

                if (!isFailed)
                {
                    await Task.Delay(MillisecondsTimeout);
                }
            }

            return isFailed;
        }

        private static StreamReader CreateStreamReader(HttpWebRequest req)
        {
            var reply = (HttpWebResponse)req.GetResponse();
            var stream = reply.GetResponseStream();
            var reader = new StreamReader(stream);

            return reader;
        }

        private static HttpWebRequest CreateSubscribeRequest(string region, string key)
        {
            var apiUrl = "http://api.sportradar.com/";            
            //var apiUrl = "http://ha.nexdev.net:7206/V1/api/";
            //var apiUrl = "http://localhost:61092/api/";
            var pushApiPath = $"soccer-xt3/{region}/stream/events/subscribe?api_key={key}&format=json";

            var formattedEndpoint = $"{apiUrl}{pushApiPath}";

            Console.WriteLine($"listen {formattedEndpoint}");

            var req = (HttpWebRequest)HttpWebRequest.Create(formattedEndpoint);
            req.AllowAutoRedirect = false;

            WebResponse reply;

            try
            {
                req.GetResponse();
            }
            catch (WebException e)
            {
                reply = e.Response;
                var redirectUrl = reply.Headers["Location"];
                req = (HttpWebRequest)HttpWebRequest.Create(new Uri(redirectUrl));
                req.KeepAlive = true;
            }

            return req;
        }

        private static void ProcessPayloads(StreamReader reader, string region)
        {
            string line;

            do
            {
                line = reader.ReadLine();

                Console.WriteLine($"{DateTime.Now} - region {region} Receiving: {line}");

            } while (!string.IsNullOrWhiteSpace(line));
        }
    }
}
